      ts_lex_state_0:
      if (eof) ADVANCE(29);
      TS_LEX_ADVANCE_MAP_SORTED(ts_lex_advance_map_0);
      if (('\t' <= lookahead && lookahead <= '\r') ||
          lookahead == ' ') TS_LEX_REPEAT(true, ts_lex_state_0);
      if (('1' <= lookahead && lookahead <= '9')) ADVANCE(117);
      if (('A' <= lookahead && lookahead <= '_') ||
          ('a' <= lookahead && lookahead <= 'z')) ADVANCE(126);
      END_STATE();
    case 1:
      ts_lex_state_1:
      if (eof) ADVANCE(29);
      TS_LEX_ADVANCE_MAP_SORTED(ts_lex_advance_map_1);
      if (('\t' <= lookahead && lookahead <= '\r') ||
          lookahead == ' ') TS_LEX_REPEAT(true, ts_lex_state_1);
      if (('1' <= lookahead && lookahead <= '9')) ADVANCE(117);
      if (('A' <= lookahead && lookahead <= 'Z') ||
          lookahead == '_' ||
          ('a' <= lookahead && lookahead <= 'z')) ADVANCE(126);
      END_STATE();
    case 2:
      ts_lex_state_2:
      if (eof) ADVANCE(29);
      TS_LEX_ADVANCE_MAP_SORTED(ts_lex_advance_map_2);
